import React, { useState } from 'react';
import { register, login } from '../services/api';

export default function Login({ onLogin }){
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [mode, setMode] = useState('login');
  const [err, setErr] = useState(null);

  async function submit(e){
    e.preventDefault();
    try{
      const res = mode==='login' ? await login(username,password) : await register(username,password);
      if (res.msg === 'ok'){
        onLogin(res.user || {username});
      } else { setErr(JSON.stringify(res)); }
    }catch(e){
      const msg = String(e);
      // convert generic fetch failure into something user-friendly
      if (msg.includes('NetworkError')) {
        setErr('Unable to reach the server. Please make sure the backend is running and try again.');
      } else {
        setErr(msg);
      }
    }
  }

  return (
    <div style={{display:'flex',justifyContent:'center',alignItems:'center',minHeight:'100vh',background:'linear-gradient(135deg, #f5f7fa 0%, #e2e8f0 100%)'}}>
      <form onSubmit={submit} style={{width:400,padding:48,background:'white',borderRadius:16,boxShadow:'0 12px 24px rgba(0,0,0,0.12)',border:'1px solid #e2e8f0'}}>
        {/* FocusGuard Branding */}
        <div style={{textAlign:'center',marginBottom:36}}>
          <div style={{fontSize:40,marginBottom:12}}>👁️</div>
          <h1 style={{color:'#1e3a5f',margin:'0 0 6px 0',fontSize:32,fontWeight:700}}>FocusGuard</h1>
          <p style={{color:'#6b7c98',margin:0,fontSize:14,letterSpacing:0.5}}>Stay focused, stay aware</p>
        </div>

        {/* Form Title */}
        <h2 style={{textAlign:'center',marginBottom:32,color:'#2d5a8c',marginTop:0,fontSize:20,fontWeight:600}}>{mode==='login' ? 'Welcome Back' : 'Create Your Account'}</h2>

        {/* Username Field */}
        <div style={{marginBottom:20}}>
          <label style={{display:'block',marginBottom:8,fontWeight:600,color:'#1a2a3f',fontSize:13}}>Username</label>
          <input placeholder='Enter your username' value={username} onChange={e=>setUsername(e.target.value)} required style={{margin:0,width:'100%',padding:'12px 14px',border:'2px solid #e2e8f0',borderRadius:8,fontSize:14,color:'#1a2a3f',fontFamily:'inherit',transition:'all 0.3s ease',background:'#f5f7fa'}} onFocus={e=>{e.target.style.borderColor='#2d5a8c';e.target.style.background='white'}} onBlur={e=>{e.target.style.borderColor='#e2e8f0';e.target.style.background='#f5f7fa'}} />
        </div>

        {/* Password Field */}
        <div style={{marginBottom:28}}>
          <label style={{display:'block',marginBottom:8,fontWeight:600,color:'#1a2a3f',fontSize:13}}>Password</label>
          <input placeholder='Enter your password' type='password' value={password} onChange={e=>setPassword(e.target.value)} required style={{margin:0,width:'100%',padding:'12px 14px',border:'2px solid #e2e8f0',borderRadius:8,fontSize:14,color:'#1a2a3f',fontFamily:'inherit',transition:'all 0.3s ease',background:'#f5f7fa'}} onFocus={e=>{e.target.style.borderColor='#2d5a8c';e.target.style.background='white'}} onBlur={e=>{e.target.style.borderColor='#e2e8f0';e.target.style.background='#f5f7fa'}} />
        </div>

        {/* Submit Button */}
        <button type='submit' style={{width:'100%',padding:14,marginBottom:18,background:'linear-gradient(135deg, #2d5a8c 0%, #1e3a5f 100%)',color:'white',border:'none',borderRadius:8,fontWeight:600,fontSize:15,cursor:'pointer',transition:'all 0.3s ease',boxShadow:'0 4px 12px rgba(45,90,140,0.25)'}} onMouseEnter={e=>e.target.style.boxShadow='0 6px 20px rgba(45,90,140,0.35)'} onMouseLeave={e=>e.target.style.boxShadow='0 4px 12px rgba(45,90,140,0.25)'}>{mode==='login' ? 'Login' : 'Register'}</button>

        {/* Toggle Mode Button */}
        <div style={{textAlign:'center',marginBottom:24}}>
          <button type='button' onClick={()=>setMode(mode==='login'?'register':'login')} style={{background:'none',color:'#2d5a8c',padding:0,textDecoration:'none',fontWeight:600,cursor:'pointer',boxShadow:'none',fontSize:14,border:'none',transition:'color 0.2s ease'}} onMouseEnter={e=>e.target.style.color='#00a86b'} onMouseLeave={e=>e.target.style.color='#2d5a8c'}>{mode==='login' ? 'Need an account? Sign up' : 'Already have an account? Login'}</button>
        </div>

        {/* Error Message */}
        {err && <div style={{color:'#c73a1d',marginTop:16,padding:14,backgroundColor:'#fef2f2',borderRadius:8,fontSize:13,borderLeft:'4px solid #c73a1d',fontWeight:500}}>{err}</div>}
      </form>
    </div>
  );
}
